func:
var on = (msg.payload === 1 || msg.payload === true);
var was = flow.get('sp_enabled') === true;
flow.set('sp_enabled', on);

if (on && !was) {
    // Fresh enable clears any failed-probe lockout
    var st = flow.get('sp_st');
    if (st && typeof st === 'object') {
        st.backoffMs = 300000;
        st.backoffUntil = 0;
        st.vocAtFail = 0;
        flow.set('sp_st', st);
    }
}

node.status({
    fill: on ? 'green' : 'grey',
    shape: 'dot',
    text: on ? 'ENABLED' : 'DISABLED'
});
return { payload: 'save' };

var val = Number(msg.payload);
if (!isFinite(val) || val < 100 || val > 2000) return null;
flow.set('sp_p_rated', val);
node.status({ fill: 'blue', shape: 'dot', text: val + 'W rated' });
return { payload: 'save' };

var v = Number(msg.payload);
if (!isFinite(v) || v < 0 || v > 150) return null;
flow.set('sp_pv_voltage', { v: v, ts: Date.now() });
node.status({ fill: v > 30 ? 'yellow' : 'grey', shape: 'dot', text: v.toFixed(1) + ' V' });
return null;

var w = Number(msg.payload);
if (!isFinite(w) || w < 0 || w > 20000) return null;
flow.set('sp_pv_power', { v: w, ts: Date.now() });
node.status({ fill: w > 5 ? 'yellow' : 'grey', shape: 'dot', text: w.toFixed(0) + ' W' });
return null;

var w = Number(msg.payload);
if (!isFinite(w) || w < 0 || w > 20000) return null;
var now = Date.now();
flow.set('sp_ac_load', { v: w, ts: now });

// Time-based rolling window (not sample-count-based: the dbus update rate
// is not a fixed 1 Hz, so counting samples would give an unknown window).
var s = flow.get('sp_load_window') || [];
s.push({ t: now, w: w });
var cutoff = now - 60000;
while (s.length && s[0].t < cutoff) s.shift();
if (s.length > 300) s.splice(0, s.length - 300);
flow.set('sp_load_window', s);

var sum = 0;
for (var i = 0; i < s.length; i++) sum += s[i].w;
var avg = sum / s.length;
flow.set('sp_ac_load_avg', { v: avg, ts: now });

node.status({
    fill: 'blue', shape: 'dot',
    text: w.toFixed(0) + 'W now, ' + avg.toFixed(0) + 'W avg (' + s.length + ' samples)'
});
return null;

var pct = Number(msg.payload);
if (!isFinite(pct) || pct < 0 || pct > 100) return null;
flow.set('sp_soc', { v: pct, ts: Date.now() });
var fill = pct > 50 ? 'green' : (pct > 30 ? 'yellow' : 'red');
node.status({ fill: fill, shape: 'dot', text: pct.toFixed(1) + ' %' });
return null;

// + = charging, - = discharging. This is the primary truth signal:
// 'no cycling in storage' means this stays near zero.
var w = Number(msg.payload);
if (!isFinite(w) || Math.abs(w) > 30000) return null;
flow.set('sp_batt_power', { v: w, ts: Date.now() });
node.status({
    fill: w < -50 ? 'yellow' : 'green',
    shape: 'dot',
    text: (w >= 0 ? '+' : '') + w.toFixed(0) + ' W' + (w < -50 ? ' (discharging)' : '')
});
return null;

// 0 = AC-in 1 (shore), 1 = AC-in 2, 240 = disconnected/inverting.
// Lets the engine verify its commands actually took effect and detect
// an absent shore connection before probing.
var v = Number(msg.payload);
if (!isFinite(v)) return null;
flow.set('sp_active_input', { v: v, ts: Date.now() });
var names = { 0: 'AC-in 1', 1: 'AC-in 2', 240: 'inverting' };
node.status({
    fill: v === 240 ? 'yellow' : 'green',
    shape: 'dot',
    text: names[v] || ('code ' + v)
});
return null;

// === Solar Priority — Decision Engine v2 ===
//
// Goal: while plugged in and in storage (battery held at ~60% by the Max
// Charge slider), power AC loads from solar whenever the panels can carry
// them — with as close to zero energy cycled through the battery as possible.
//
// States: shore -> probe (60s MPPT ramp) -> solar -> shore
//
// Robustness rules:
//  - Battery power is the primary truth signal: solar mode is only healthy
//    while the pack is not discharging. PV-vs-load only feeds the estimate.
//  - Every input is timestamped; anything stale (>STALE_MS) forces shore.
//  - Safety exits to shore ignore cooldown; cooldown/backoff only gate
//    shore -> probe.
//  - Failed probes back off exponentially (5m -> 60m); a materially brighter
//    sky (Voc +5V), a >=30 min stable solar stint, or a re-enable resets it.
//  - The desired IgnoreAcIn1 value is re-asserted every 30s while enabled,
//    so a vebus reset or an external write cannot leave the system diverged.
//  - /Ac/ActiveIn/ActiveInput feedback detects an ineffective command
//    (wrong service selected) and an absent shore connection.
//  - Self-tune only trusts a probe when the battery was discharging (proof
//    the MPPTs were unthrottled): a throttled MPPT reads load, not capacity.

// ---- Tunables ----
var SOLAR_MARGIN      = 1.2;      // estimate must exceed avg load by 20%
var MIN_EST_W         = 100;      // minimum estimate worth probing
var READY_MS          = 30000;    // probe conditions must hold this long
var RAMP_MS           = 60000;    // MPPT ramp time during probe
var EVAL_MS           = 15000;    // averaging window at the end of the ramp
var DISCHARGE_TOL_W   = 50;       // battery discharge below this = not cycling
var LOAD_EXCEED_MS    = 15000;    // sustained moderate deficit before exit
var SURGE_W           = 400;      // battery discharge that counts as a big load
var SURGE_MS          = 3000;     // sustained surge before immediate exit
var COOLDOWN_MS       = 300000;   // min time between transitions (5 min)
var BACKOFF_MAX_MS    = 3600000;  // failed-probe backoff cap (60 min)
var STABLE_MS         = 1800000;  // solar stint >= 30 min resets backoff
var VOC_RETRY_DELTA_V = 5;        // Voc rise since last failure releases backoff
var MIN_SOC           = 40;       // never probe below this SOC
var SOC_EMERGENCY     = 30;       // immediate shore + 1h lockout
var SOC_DRIFT_MAX     = 2;        // % below solar-entry SOC -> exit
var STALE_MS          = 30000;    // input older than this = missing
var ASSERT_MS         = 30000;    // re-assert command interval (enabled only)
var FEEDBACK_GRACE_MS = 90000;    // time allowed for ActiveInput to match
// Voc estimation model (panel-specific — see SETUP comment)
var VOC_ZERO    = 30;             // V below which power is negligible
var VOC_FULL    = 80;             // V at full sun
var PRODUCING_W = 30;             // above this /Pv/V reads Vmp, not Voc

var now = Date.now();

function fresh(key) {
    var o = flow.get(key);
    if (!o || typeof o.v !== 'number' || !isFinite(o.v)) return null;
    if (now - o.ts > STALE_MS) return null;
    return o.v;
}

var enabled = flow.get('sp_enabled') === true;
var voc     = fresh('sp_pv_voltage');
var pv      = fresh('sp_pv_power');
var soc     = fresh('sp_soc');
var batt    = fresh('sp_batt_power');   // W: + charging, - discharging
var loadNow = fresh('sp_ac_load');
var loadAvg = fresh('sp_ac_load_avg');
var feed    = fresh('sp_active_input'); // 0=ACin1, 1=ACin2, 240=inverting, null=unknown

var gain = flow.get('sp_gain');
if (typeof gain !== 'number' || !isFinite(gain) || gain < 0.3 || gain > 3) gain = 1.0;
var pRated = flow.get('sp_p_rated');
if (typeof pRated !== 'number' || !isFinite(pRated) || pRated < 100 || pRated > 2000) pRated = 500;

var st = flow.get('sp_st');
if (!st || typeof st !== 'object' || !st.state) {
    st = {
        state: 'shore', desired: 0, lastSent: null, lastAssert: 0,
        lastTransition: now, probeStart: 0, probeEst: 0, evalPv: [], evalBatt: [],
        readySince: 0, loadExceedStart: 0, surgeStart: 0,
        backoffMs: COOLDOWN_MS, backoffUntil: 0, vocAtFail: 0,
        socEntry: 0, solarSince: 0
    };
}

var transition = null;
var persist = false;
var statusFill = 'grey', statusText = '';

function toShore(reason) {
    st.desired = 0;
    st.state = 'shore';
    st.lastTransition = now;
    st.readySince = 0;
    st.loadExceedStart = 0;
    st.surgeStart = 0;
    st.probeStart = 0;
    st.evalPv = [];
    st.evalBatt = [];
    transition = '-> SHORE (' + reason + ')';
    statusText = transition;
}

function escalateBackoff() {
    st.backoffUntil = now + st.backoffMs;
    st.backoffMs = Math.min(st.backoffMs * 2, BACKOFF_MAX_MS);
}

function lockout() {
    st.backoffMs = BACKOFF_MAX_MS;
    st.backoffUntil = now + BACKOFF_MAX_MS;
}

function applyGain(pvAvg) {
    // Blend the observed capacity/estimate ratio into the gain
    if (st.probeEst <= 0) return;
    var r = Math.max(0, Math.min(3, pvAvg / st.probeEst));
    gain = Math.max(0.3, Math.min(3.0, gain * (0.85 + 0.15 * r)));
    flow.set('sp_gain', gain);
    persist = true;
}

var missing = [];
if (voc === null) missing.push('Voc');
if (pv === null) missing.push('PV');
if (soc === null) missing.push('SOC');
if (batt === null) missing.push('Batt');
if (loadNow === null || loadAvg === null) missing.push('Load');

if (!enabled) {
    if (st.state !== 'shore') toShore('disabled');
    else statusText = 'DISABLED';
    statusFill = 'grey';

} else if (missing.length) {
    if (st.state !== 'shore') toShore('no/stale data: ' + missing.join(','));
    else statusText = 'No/stale data: ' + missing.join(', ');
    statusFill = 'red';

} else if (soc < SOC_EMERGENCY && st.state !== 'shore') {
    lockout();
    toShore('EMERGENCY SOC ' + soc.toFixed(1) + '%');
    statusFill = 'red';

} else {
    // ---- Available-solar estimate ----
    // Idle MPPT: /Pv/V is open-circuit voltage -> Voc model.
    // Producing MPPT: /Pv/V is Vmp (lower), but actual PV power is a live
    // lower bound on capacity -> take the larger of the two.
    var ratio = Math.max(0, Math.min(1, (voc - VOC_ZERO) / (VOC_FULL - VOC_ZERO)));
    var vocEst = pRated * ratio * gain;
    var est = (pv >= PRODUCING_W) ? Math.max(pv, vocEst) : vocEst;
    var discharge = -batt;
    var sinceTrans = now - st.lastTransition;

    if (st.state === 'shore') {
        // Commanded shore but still inverting well past the transfer grace:
        // shore power is absent — probing would leave no fallback.
        var shoreMissing = (feed === 240 && sinceTrans > FEEDBACK_GRACE_MS);

        // A materially brighter sky releases a failed-probe backoff early
        if (st.backoffUntil > now && st.vocAtFail > 0 && voc >= st.vocAtFail + VOC_RETRY_DELTA_V) {
            st.backoffUntil = 0;
            st.backoffMs = COOLDOWN_MS;
            st.vocAtFail = 0;
        }

        var ready = !shoreMissing &&
                    est >= MIN_EST_W &&
                    est >= loadAvg * SOLAR_MARGIN &&
                    soc >= MIN_SOC;
        if (ready) { if (!st.readySince) st.readySince = now; }
        else st.readySince = 0;

        var gateOk = sinceTrans >= COOLDOWN_MS && now >= st.backoffUntil;

        if (ready && gateOk && (now - st.readySince) >= READY_MS) {
            st.state = 'probe';
            st.desired = 1;
            st.probeStart = now;
            st.probeEst = est;
            st.evalPv = [];
            st.evalBatt = [];
            st.lastTransition = now;
            st.surgeStart = 0;
            st.readySince = 0;
            transition = '-> PROBE (est ' + est.toFixed(0) + 'W vs load ' + loadAvg.toFixed(0) + 'W, g=' + gain.toFixed(2) + ')';
            statusFill = 'yellow';
            statusText = transition;
        } else {
            statusFill = shoreMissing ? 'red' : 'blue';
            statusText = (shoreMissing ? 'NO SHORE? | ' : 'SHORE | ') +
                'est ' + est.toFixed(0) + 'W load ' + loadAvg.toFixed(0) + 'W Voc ' +
                voc.toFixed(0) + 'V SOC ' + soc.toFixed(0) + '% g ' + gain.toFixed(2);
            if (now < st.backoffUntil) {
                statusText += ' [backoff ' + Math.ceil((st.backoffUntil - now) / 60000) + 'm]';
            } else if (sinceTrans < COOLDOWN_MS) {
                statusText += ' [cd ' + Math.ceil((COOLDOWN_MS - sinceTrans) / 1000) + 's]';
            } else if (ready) {
                statusText += ' [confirm ' + Math.ceil((READY_MS - (now - st.readySince)) / 1000) + 's]';
            }
        }

    } else if (st.state === 'probe') {
        var elapsed = now - st.probeStart;

        // A load bigger than the estimate appeared mid-probe: cannot succeed
        if (loadNow * SOLAR_MARGIN > st.probeEst) {
            if (!st.surgeStart) st.surgeStart = now;
        } else st.surgeStart = 0;

        if (st.surgeStart && now - st.surgeStart >= SURGE_MS) {
            toShore('big load during probe (' + loadNow.toFixed(0) + 'W)');
            statusFill = 'blue';

        } else if (elapsed < RAMP_MS) {
            if (elapsed >= RAMP_MS - EVAL_MS) {
                st.evalPv.push(pv);
                st.evalBatt.push(batt);
            }
            statusFill = 'yellow';
            statusText = 'PROBE ' + Math.ceil((RAMP_MS - elapsed) / 1000) + 's | PV ' +
                pv.toFixed(0) + 'W batt ' + batt.toFixed(0) + 'W load ' + loadNow.toFixed(0) + 'W';

        } else {
            var pvAvg = st.evalPv.length ?
                st.evalPv.reduce(function (a, b) { return a + b; }, 0) / st.evalPv.length : pv;
            var battAvg = st.evalBatt.length ?
                st.evalBatt.reduce(function (a, b) { return a + b; }, 0) / st.evalBatt.length : batt;

            if (feed === 0) {
                // Still on AC-in 1 after 60s of commanding ignore: the write
                // is not taking effect. Long lockout, no gain update — this
                // says nothing about the panels.
                node.error('Solar Priority: IgnoreAcIn1 has no effect — check the AC Input Control / Feedback service selection');
                lockout();
                toShore('FAULT: AC control ineffective');
                statusFill = 'red';

            } else if (battAvg > -DISCHARGE_TOL_W) {
                // Battery not discharging: solar carries everything (AC+DC+losses)
                if (pvAvg > st.probeEst) applyGain(pvAvg); // lower-bound evidence only
                st.state = 'solar';
                st.socEntry = soc;
                st.solarSince = now;
                st.lastTransition = now;
                st.loadExceedStart = 0;
                st.surgeStart = 0;
                st.backoffMs = COOLDOWN_MS;
                st.backoffUntil = 0;
                st.vocAtFail = 0;
                transition = '-> SOLAR (PV ' + pvAvg.toFixed(0) + 'W, batt ' + battAvg.toFixed(0) + 'W, g=' + gain.toFixed(2) + ')';
                statusFill = 'green';
                statusText = transition;

            } else {
                // Battery discharging -> MPPTs were unthrottled -> pvAvg is
                // the real available capacity right now. Tune and back off.
                applyGain(pvAvg);
                st.vocAtFail = voc;
                escalateBackoff();
                toShore('probe failed: PV ' + pvAvg.toFixed(0) + 'W, batt ' + battAvg.toFixed(0) + 'W');
                statusFill = 'blue';
            }
        }

    } else { // ---- SOLAR ----
        // A long stable stint proves the estimate is sound again
        if (st.backoffMs !== COOLDOWN_MS && now - st.solarSince >= STABLE_MS) {
            st.backoffMs = COOLDOWN_MS;
        }

        if (discharge > DISCHARGE_TOL_W) { if (!st.loadExceedStart) st.loadExceedStart = now; }
        else st.loadExceedStart = 0;
        if (discharge > SURGE_W) { if (!st.surgeStart) st.surgeStart = now; }
        else st.surgeStart = 0;

        if (feed === 0 && sinceTrans > FEEDBACK_GRACE_MS) {
            // Something re-accepted AC-in 1 despite our 30s re-asserts
            node.error('Solar Priority: Quattro re-accepted AC during solar mode — standing down');
            lockout();
            toShore('FAULT: AC re-accepted externally');
            statusFill = 'red';

        } else if (soc < MIN_SOC || soc < st.socEntry - SOC_DRIFT_MAX) {
            st.vocAtFail = voc;
            escalateBackoff();
            toShore('SOC ' + soc.toFixed(1) + '% (entry ' + st.socEntry.toFixed(1) + '%)');
            statusFill = 'blue';

        } else if (st.surgeStart && now - st.surgeStart >= SURGE_MS) {
            toShore('big load: batt -' + discharge.toFixed(0) + 'W, load ' + loadNow.toFixed(0) + 'W');
            statusFill = 'blue';

        } else if (st.loadExceedStart && now - st.loadExceedStart >= LOAD_EXCEED_MS) {
            st.vocAtFail = voc;
            escalateBackoff();
            toShore('deficit: batt -' + discharge.toFixed(0) + 'W for ' + (LOAD_EXCEED_MS / 1000) + 's');
            statusFill = 'blue';

        } else if (st.loadExceedStart || st.surgeStart) {
            var left = st.surgeStart ?
                Math.ceil((SURGE_MS - (now - st.surgeStart)) / 1000) :
                Math.ceil((LOAD_EXCEED_MS - (now - st.loadExceedStart)) / 1000);
            statusFill = 'yellow';
            statusText = 'SOLAR! batt -' + discharge.toFixed(0) + 'W PV ' + pv.toFixed(0) +
                'W load ' + loadNow.toFixed(0) + 'W [shore in ' + left + 's]';

        } else {
            statusFill = 'green';
            statusText = 'SOLAR | PV ' + pv.toFixed(0) + 'W batt ' + (batt >= 0 ? '+' : '') +
                batt.toFixed(0) + 'W load ' + loadNow.toFixed(0) + 'W SOC ' + soc.toFixed(1) + '%';
        }
    }
}

// ---- Command emission ----
// Send on change; while enabled, also re-assert every ASSERT_MS so a vebus
// restart or external write cannot leave the system diverged. When disabled,
// never re-assert (the user may control IgnoreAcIn1 manually).
var cmdMsg = null;
if (st.lastSent !== st.desired || (enabled && now - st.lastAssert >= ASSERT_MS)) {
    st.lastSent = st.desired;
    st.lastAssert = now;
    cmdMsg = { payload: st.desired };
}

flow.set('sp_st', st);
node.status({ fill: statusFill, shape: 'dot', text: statusText });

return [
    cmdMsg,
    transition ? { payload: transition, topic: 'solar-priority' } : null,
    persist ? { payload: 'save' } : null
];

initialize:
// Reset the state machine on every deploy: always start on shore.
// Gain / enable / rated power are restored from the state file ~6s later.
flow.set('sp_st', null);

func:
// Any uncaught error in the decision engine forces shore power
var st = flow.get('sp_st');
if (st && typeof st === 'object') {
    st.state = 'shore';
    st.desired = 0;
    st.lastSent = 0;
    st.lastAssert = Date.now();
    flow.set('sp_st', st);
}
var errText = (msg.error && msg.error.message) || 'unknown';
node.error('Solar Priority decision error — forcing shore: ' + errText);
node.status({ fill: 'red', shape: 'ring', text: 'error -> shore: ' + errText });
return { payload: 0 };

// Payload: first line = writable state dir (discovered by the shell,
// running as the same user as Node-RED), rest = saved JSON (may be empty)
var raw = String(msg.payload);
var nl = raw.indexOf('\n');
var dir = (nl >= 0 ? raw.slice(0, nl) : raw).trim();
var rest = nl >= 0 ? raw.slice(nl + 1) : '';
if (dir) flow.set('sp_state_dir', dir);

var s = {};
try { s = JSON.parse(rest); } catch (e) { }

var enabled = s.enabled === true;
var pRated = (typeof s.pRated === 'number' && s.pRated >= 100 && s.pRated <= 2000) ? s.pRated : 500;
var gain = (typeof s.gain === 'number' && s.gain >= 0.3 && s.gain <= 3.0) ? s.gain : 1.0;

// Set flow context directly (don't depend on the switch echo), then push
// the values back into the VRM virtual switches so the dashboard matches.
flow.set('sp_enabled', enabled);
flow.set('sp_p_rated', pRated);
flow.set('sp_gain', gain);
flow.set('sp_restored', true);

node.status({
    fill: 'blue', shape: 'dot',
    text: (enabled ? 'ENABLED' : 'disabled') + ' | ' + pRated + 'W | g ' + gain.toFixed(2) + ' | ' + dir
});

return [
    { payload: { '/SwitchableOutput/output_1/Value': enabled ? 1 : 0 } },
    { payload: { '/SwitchableOutput/output_1/Value': pRated } }
];

initialize:
// Reset on every deploy: saves stay blocked until this deploy's
// discovery + restore have run (flow context survives redeploys).
flow.set('sp_restored', false);
flow.set('sp_state_dir', '');

func:
var n = (flow.get('sp_restore_retries') || 0) + 1;
if (n > 5) {
    node.status({ fill: 'red', shape: 'ring', text: 'gave up after 5 retries' });
    return null;
}
flow.set('sp_restore_retries', n);
node.status({ fill: 'yellow', shape: 'ring', text: 'switch push failed — retry ' + n + '/5 in 3s' });
return msg;

// Never save before restore has run — a startup switch echo would
// otherwise overwrite the state file with defaults.
if (flow.get('sp_restored') !== true) return null;

// Only save once the startup discovery has found a writable dir — never guess
var dir = flow.get('sp_state_dir');
if (!dir) return null;
msg.filename = dir + '/solar-priority-state.json';

var gain = flow.get('sp_gain');
var pRated = flow.get('sp_p_rated');
msg.payload = JSON.stringify({
    enabled: flow.get('sp_enabled') === true,
    pRated: (typeof pRated === 'number') ? pRated : 500,
    gain: (typeof gain === 'number' && isFinite(gain)) ? gain : 1.0,
    savedAt: new Date().toISOString()
}, null, 2);

node.status({ fill: 'grey', shape: 'dot', text: 'saved ' + msg.filename });
return msg;
